'use strict';
// Global Interface Update: UI state only, never stored in the career model.
const GlobalInterface6={tab:'five',selected:null,
 select(id){if(owned().some(p=>p.id===id&&!p.retired)){this.selected=id;render();}},
 setTab(tab){if(['five','bench','contracts'].includes(tab)){this.tab=tab;render();}},
 squad(){
  const ps=roster(),reserve=owned().filter(p=>!p.active&&!p.retired),p=owned().find(p=>p.id===this.selected&&!p.retired)||ps[0],r=readiness33C();
  if(p)this.selected=p.id;
  const card=(p,i)=>'<article class="g6-player c-player '+(p.id===this.selected?'is-selected':'')+'"><button class="g6-select" type="button" onclick="GlobalInterface6.select('+p.id+')" aria-label="Выбрать '+esc(p.name)+'" aria-pressed="'+(p.id===this.selected)+'"><div class="g6-player-art"><span class="g6-position">'+String(p.role+1).padStart(2,'0')+'</span><b class="g6-rating">'+Math.round(p.skill)+'</b>'+portrait20(p)+'</div><div class="g6-player-name"><h3>'+esc(p.name)+'</h3><small>'+esc(ROLES[p.role])+'</small></div></button><div class="g6-vitals">'+[['Форма',p.form],['Энергия',100-p.fatigue]].map(([label,v])=>'<div><span>'+label+'</span><b>'+Math.round(v)+(label==='Энергия'?'%':'')+'</b><i style="--value:'+clamp(v)+'%"></i></div>').join('')+'</div><div class="actions">'+btn('Профиль','profile('+p.id+')')+btn('Сравнить','openCompare33C('+p.id+')')+'</div></article>';
  return '<div class="g6-squad"><nav class="g6-tabs" aria-label="Управление составом">'+[['five','Основная пятёрка'],['bench','Резерв'],['contracts','Контракты']].map(([key,label])=>'<button type="button" aria-pressed="'+(this.tab===key)+'" onclick="GlobalInterface6.setTab(\''+key+'\')">'+label+'</button>').join('')+'</nav><div class="g6-squad-title"><div><span class="eyebrow">'+esc(my().name)+' / ROSTER MANAGEMENT</span><h1>'+({five:'Основная пятёрка',bench:'Скамейка запасных',contracts:'Контракты команды'})[this.tab]+'</h1></div><div class="g6-compact-metrics">'+[['OVR',r.ovr],['SIN',r.sin],['Форма',r.form],['Энергия',r.energy]].map(([k,v])=>'<div><small>'+k+'</small><strong>'+Math.round(v)+'</strong></div>').join('')+'</div></div>'+
  (this.tab==='five'?'<div class="actions g6-display">'+btn('Карточки',"setSquadMode33C('cards')")+btn('Таблица',"setSquadMode33C('table')")+'</div>'+(Arena33C.squadMode==='table'?'<section class="neon-squad">'+neonSquadTable(ps)+'</section>':'<section class="g6-five">'+ps.map(card).join('')+'</section>'):this.tab==='bench'?'<section class="g6-five g6-reserves">'+reserve.map(card).join('')+(reserve.length?'':'<div class="panel"><h2>Место для следующего усиления</h2><p>Резерв свободен: 0 / 3.</p>'+btn('Найти игрока',"go('market')",true)+'</div>')+'</section>':'<section class="panel"><h2>Сроки и условия</h2>'+playerTable(owned().filter(p=>!p.retired),true)+'</section>')+
  '<div class="g6-management"><section class="panel"><span class="eyebrow">BENCH / '+reserve.length+' OF 3</span><h2>Глубина состава</h2><div class="g6-bench">'+reserve.map(p=>'<button onclick="profile('+p.id+')">'+portrait20(p)+'<b>'+esc(p.name)+'</b></button>').join('')+Array.from({length:Math.max(0,3-reserve.length)},()=>'<span>+<small>Свободный слот</small></span>').join('')+'</div>'+btn('Поиск усиления',"go('market')")+'</section><section class="panel g6-selected"><span class="eyebrow">SELECTED PLAYER</span><h2>'+esc(p?.name||'Игрок не выбран')+'</h2>'+(p?'<div class="g6-detail">'+portrait20(p)+'<div><p>'+esc(ROLES[p.role])+'</p><p>Контракт: <b>'+p.contract+' дн.</b></p><p>Зарплата: <b>'+cash(p.salary)+'/нед.</b></p></div></div><div class="actions">'+btn('Профиль','profile('+p.id+')')+btn('Контракт','profile('+p.id+')')+btn('Сравнить','openCompare33C('+p.id+')')+'</div>':'')+'</section><section class="panel"><span class="eyebrow">CLUB CHEMISTRY</span><h2>Сыгранность пятёрки</h2><strong class="g6-sin">SIN '+Math.round(r.sin)+'</strong><div class="g6-role-chain">'+ps.map(p=>'<span>'+String(p.role+1).padStart(2,'0')+'</span>').join('')+'</div>'+btn('Управлять подготовкой',"go('tactics')",true)+'<details><summary>Как считается SIN</summary>'+amTeamCard(my())+'</details></section></div><details class="g6-legacy"><summary>Поддержка клуба и архив состава</summary>'+amTeamCard(my())+'<p>Болельщики: '+Math.round(Fans4.support(my()).fans).toLocaleString('ru-RU')+'</p><p>'+S.players.filter(p=>p.retired&&p.retiredFromTeam===S.club).map(p=>esc(p.name)).join(' · ')+'</p></details></div>';
 },
 decorate(){
  if(typeof document.querySelector!=='function'||!S)return;
  const app=$('app');app.classList.add('g6-view');
  if(!app.querySelector('.g6-context')&&!['home','squad','match','player'].includes(page)){
   const e=nextEvent(),r=readiness33C();let content='';
   if(page==='market'||page==='players')content='<div><span class="eyebrow">SCOUTING DESK</span><h2>Следующее усиление</h2><p>Профили, роли и условия — до решения о трансфере.</p></div><div class="g6-scout-strip">'+S.players.filter(p=>!p.retired&&p.team!==S.club).sort((a,b)=>b.skill-a.skill).slice(0,3).map(p=>'<button onclick="profile('+p.id+')">'+portrait20(p)+'<span><b>'+esc(p.name)+'</b><small>'+esc(ROLES[p.role])+' / '+Math.round(p.skill)+' OVR</small></span></button>').join('')+'</div>';
   else if(['tactics','bootcamp','development'].includes(page))content='<div><span class="eyebrow">PERFORMANCE / '+esc(my().short)+'</span><h2>Пятёрка. Одна цель.</h2><p>Форма '+Math.round(r.form)+' / Энергия '+Math.round(r.energy)+'% / SIN '+Math.round(r.sin)+'</p></div><div class="g6-scout-strip">'+roster().map(p=>'<button onclick="profile('+p.id+')">'+portrait20(p)+'<span><b>'+esc(p.name)+'</b><small>POS '+(p.role+1)+'</small></span></button>').join('')+'</div>';
   else if(['calendar','qualifiers','bracket','ranking','trophies'].includes(page))content='<div><span class="eyebrow">COMPETITION / '+esc(my().short)+'</span><h2>'+esc(e?.name||'Новая глава сезона')+'</h2><p>'+esc(e?date(e.day):date(S.day))+' / '+esc(e?.venue||'Турнирная сцена')+'</p></div><div class="g6-context-crest">'+clubAvatar12(my(),false)+'</div>';
   else if(page==='finance')content='<div><span class="eyebrow">CLUB BUSINESS</span><h2>Ресурсы для следующей победы</h2><p>Текущий бюджет клуба</p></div><strong class="g6-context-money">'+cash(S.budget)+'</strong>';
   if(content){const el=document.createElement('section');el.className='g6-context';el.innerHTML=content;app.prepend(el);}
  }

  const toolbar=$('matchdayTools6');if(page==='squad'&&toolbar)toolbar.hidden=true;if(toolbar&&!toolbar.hidden){
   const category=({market:'TRANSFER CENTRE',calendar:'COMPETITION HUB',bracket:'TOURNAMENT BRACKET',tactics:'PERFORMANCE LAB',bootcamp:'TRAINING CAMP',finance:'CLUB BUSINESS',squad:'ROSTER MANAGEMENT',trophies:'LEGACY & HONOURS',players:'PLAYER DATABASE',clubs:'WORLD SCENE',ranking:'POWER RANKINGS',qualifiers:'ROAD TO THE MAIN STAGE',development:'CLUB DEVELOPMENT',history:'MATCH ARCHIVE',settings:'CAREER CONTROL',match:'MATCHDAY LIVE'})[page]||'CLUB OPERATIONS';
   toolbar.dataset.category=category;
   const small=toolbar.querySelector('small');if(small)small.textContent=category+' / '+my().short;
  }
 }
};
const squadBeforeGlobal6=squad;squad=function(){return GlobalInterface6.squad();};
const renderBeforeGlobal6=render;render=function(...args){const result=renderBeforeGlobal6(...args);GlobalInterface6.decorate();return result;};
const freshBeforeGlobal6=fresh,migrateBeforeGlobal6=migrate;
fresh=function(...args){GlobalInterface6.tab='five';GlobalInterface6.selected=null;return freshBeforeGlobal6(...args);};
migrate=function(...args){GlobalInterface6.tab='five';GlobalInterface6.selected=null;return migrateBeforeGlobal6(...args);};
const patchBeforeGlobal6=patchViewV1;
patchViewV1=function(...args){return '<section class="panel"><span class="eyebrow">V6.0 / GLOBAL INTERFACE UPDATE</span><h1>Новая визуальная эпоха клуба</h1><p>Единое чёрно-лаймовое оформление всех вкладок и заставок. Новый экран состава: карточки по позициям, выбор игрока, резерв и контракты. Обновлены центр трансферов, подготовка, соревнования, финансы и навигация.</p><p>Игровые показатели, формула матча и сохранения продолжают работать по прежним правилам.</p></section><details><summary>История обновлений</summary>'+patchBeforeGlobal6(...args)+'</details>';};
